import { useState } from "react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { ChevronRightIcon } from "lucide-react";

interface OnboardingContentProps {
  onContinue: (data: { role: string; automation: string[] }) => void;
}

const roles = [
  { id: "product-manager", label: "Product Manager" },
  { id: "developer", label: "Developer" },
  { id: "designer", label: "Designer" },
  { id: "ops", label: "Ops" },
  { id: "founder", label: "Founder" },
  { id: "other", label: "Other" }
];

const automationOptions = [
  { id: "data-collection", label: "Data collection & processing" },
  { id: "emails", label: "Sending emails or messages" },
  { id: "dashboard", label: "Dashboard updates" },
  { id: "repetitive-tasks", label: "Repetitive internal tasks" },
  { id: "ai-assistant", label: "Building your own AI assistant" },
  { id: "other", label: "Other" }
];

export const Content = ({ onContinue }: OnboardingContentProps) => {
  const [selectedRole, setSelectedRole] = useState("product-manager");
  const [selectedAutomation, setSelectedAutomation] = useState<string[]>([
    "data-collection",
    "repetitive-tasks"
  ]);

  const toggleAutomation = (option: string) => {
    setSelectedAutomation((prev) =>
      prev.includes(option) ? prev.filter((item) => item !== option) : [...prev, option]
    );
  };

  const handleContinue = () => {
    onContinue({
      role: selectedRole,
      automation: selectedAutomation
    });
  };

  return (
    <div className="min-h-screen flex-1 p-8 lg:p-16">
      <div className="mx-auto max-w-xl">
        {/* Header */}
        <div className="mb-16">
          <h1 className="text-foreground mb-4 text-3xl leading-tight font-semibold lg:text-4xl">
            Let&#39;s personalize your experience
          </h1>
          <p className="text-muted-foreground leading-relaxed">
            Tell us a bit about you so we can tailor templates, suggestions, and features to your
            needs.
          </p>
        </div>

        {/* Role Selection */}
        <div className="mb-12">
          <h4 className="text-foreground mb-8 text-xl">What best describes your role?</h4>
          <div className="grid grid-cols-2 gap-3 lg:grid-cols-3">
            {roles.map((role) => (
              <button
                key={role.id}
                onClick={() => setSelectedRole(role.id)}
                className={cn(
                  "font-inter rounded-lg border p-4 text-left font-medium transition-all duration-200 hover:shadow-sm",
                  selectedRole === role.id
                    ? "border-gray-700"
                    : "border-onboarding-option-border text-foreground hover:border-onboarding-option-border/60"
                )}>
                <div className="flex items-center gap-3">
                  <div
                    className={cn(
                      "h-2 w-2 rounded-full",
                      selectedRole === role.id ? "bg-green-400" : "bg-onboarding-option-border"
                    )}></div>
                  {role.label}
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Automation Selection */}
        <div className="mb-16">
          <h4 className="text-foreground mb-8 text-xl">What do you want to automate first?</h4>
          <div className="grid grid-cols-1 gap-3 lg:grid-cols-2">
            {automationOptions.map((option) => (
              <button
                key={option.id}
                onClick={() => toggleAutomation(option.id)}
                className={cn(
                  "font-inter rounded-lg border p-4 text-left font-medium transition-all duration-200 hover:shadow-sm",
                  selectedAutomation.includes(option.id)
                    ? "border-gray-700"
                    : "border-onboarding-option-border text-foreground hover:border-onboarding-option-border/60"
                )}>
                <div className="flex items-center gap-3">
                  <div
                    className={cn(
                      "h-2 w-2 rounded-full",
                      selectedAutomation.includes(option.id)
                        ? "bg-green-400"
                        : "bg-onboarding-option-border"
                    )}></div>
                  {option.label}
                </div>
              </button>
            ))}
          </div>
        </div>

        <div className="flex justify-center">
          <Button onClick={handleContinue} className="flex w-full justify-between" size="lg">
            Continue
            <ChevronRightIcon />
          </Button>
        </div>
      </div>
    </div>
  );
};

import { cn } from "@/lib/utils";
import { BoxIcon } from "lucide-react";

interface OnboardingStep {
  id: string;
  title: string;
  completed: boolean;
  current: boolean;
  optional?: boolean;
}

interface OnboardingSidebarProps {
  steps: OnboardingStep[];
  className?: string;
}

export const Sidebar = ({ steps, className }: OnboardingSidebarProps) => {
  return (
    <div
      className={cn(
        "relative flex min-h-screen w-80 flex-col bg-gradient-to-b from-black to-indigo-700 p-6 text-white",
        className
      )}>
      <div className="mb-12 flex items-center gap-3 pt-4">
        <BoxIcon className="size-6" />
      </div>

      {/* Steps */}
      <div className="flex-1 space-y-4">
        {steps.map((step, index) => (
          <div
            key={step.id}
            className={cn(
              "flex items-center gap-4 rounded-lg p-3 transition-all duration-200",
              step.current && "bg-white/10"
            )}>
            <div
              className={cn(
                "flex h-6 w-6 flex-shrink-0 items-center justify-center rounded-full border-2",
                step.completed
                  ? "border-green-400 bg-green-400"
                  : step.current
                    ? "border-white bg-transparent"
                    : "border-white/30"
              )}>
              {step.completed ? (
                <svg className="h-3 w-3 text-gray-800" fill="currentColor" viewBox="0 0 20 20">
                  <path
                    fillRule="evenodd"
                    d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"
                    clipRule="evenodd"
                  />
                </svg>
              ) : step.current ? (
                <div className="h-2 w-2 rounded-full bg-white"></div>
              ) : (
                <span className="text-xs text-white/60">{index + 1}</span>
              )}
            </div>
            <div className="flex-1">
              <div
                className={cn(
                  "font-inter text-sm font-medium",
                  step.current ? "text-white" : "text-white/70"
                )}>
                {step.title}
              </div>
              {step.optional && <div className="font-inter text-xs text-white/50">optional</div>}
            </div>
          </div>
        ))}
      </div>

      {/* Footer */}
      <div className="font-inter mt-auto flex justify-between pt-8 text-sm text-white/60">
        <span>Terms of Service</span>
        <span>Help Center</span>
      </div>
    </div>
  );
};

"use client";

import { useState } from "react";
import { cn } from "@/lib/utils";
import { Sidebar } from "./components/sidebar";
import { Content } from "./components/content";

const onboardingSteps = [
  {
    id: "role",
    title: "Role & Use Case",
    completed: false,
    current: true
  },
  {
    id: "template",
    title: "Choose a Template or Start from Scratch",
    completed: false,
    current: false
  },
  {
    id: "data-source",
    title: "Data Source Setup",
    completed: false,
    current: false
  },
  {
    id: "first-flow",
    title: "Build Your First Flow",
    completed: false,
    current: false,
    optional: true
  },
  {
    id: "invite-team",
    title: "Invite Team",
    completed: false,
    current: false,
    optional: true
  }
];

export default function Page() {
  const [currentStep, setCurrentStep] = useState(0);
  const [steps, setSteps] = useState(onboardingSteps);

  const handleContinue = (data: { role: string; automation: string[] }) => {
    console.log("Onboarding data:", data);

    // Mark current step as completed and move to next
    const newSteps = steps.map((step, index) => {
      if (index === currentStep) {
        return { ...step, completed: true, current: false };
      }
      if (index === currentStep + 1) {
        return { ...step, current: true };
      }
      return step;
    });

    setSteps(newSteps);
    setCurrentStep(currentStep + 1);
  };

  return (
    <div className="flex min-h-screen overflow-hidden">
      <div className="hidden lg:block">
        <Sidebar steps={steps} />
      </div>

      <Content onContinue={handleContinue} />

      <div className="border-onboarding-option-border fixed right-0 bottom-0 left-0 border-t p-4 lg:hidden">
        <div className="flex items-center justify-center gap-2">
          {steps.map((step, index) => (
            <div
              key={step.id}
              className={cn(
                "h-2 w-2 rounded-full transition-colors",
                step.completed
                  ? "bg-accent"
                  : step.current
                    ? "bg-primary"
                    : "bg-onboarding-option-border"
              )}
            />
          ))}
        </div>
        <div className="mt-2 text-center">
          <span className="text-onboarding-text-muted font-inter text-sm">
            Step {currentStep + 1} of {steps.length}
          </span>
        </div>
      </div>
    </div>
  );
}

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "cursor-pointer inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground shadow-xs hover:bg-primary/90",
        destructive:
          "bg-destructive text-white shadow-xs hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
        secondary: "bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline"
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9"
      }
    },
    defaultVariants: {
      variant: "default",
      size: "default"
    }
  }
);

function Button({
  className,
  variant,
  size,
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean;
  }) {
  const Comp = asChild ? Slot : "button";

  return (
    <Comp
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}

export { Button, buttonVariants };
